<?php require_once __DIR__.'/professional_assets/bootstrap_portal.php'; require_role(['admin','worker','doctor']);$con->query("CREATE TABLE IF NOT EXISTS nursing_notes(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,nurse_name VARCHAR(120) DEFAULT '',vitals VARCHAR(255) DEFAULT '',medication VARCHAR(255) DEFAULT '',note TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(patient_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=$con->prepare("INSERT INTO nursing_notes(patient_id,nurse_name,vitals,medication,note) VALUES(?,?,?,?,?)");$p=(int)$_POST['patient_id'];$n=trim($_POST['nurse_name']);$v=trim($_POST['vitals']);$m=trim($_POST['medication']);$note=trim($_POST['note']);$s->bind_param('issss',$p,$n,$v,$m,$note);if($s->execute())$msg='Nursing note saved.';}$patients=$con->query("SELECT patientid,patientname FROM patient ORDER BY patientname");$rows=$con->query("SELECT n.*,p.patientname FROM nursing_notes n JOIN patient p ON p.patientid=n.patient_id ORDER BY n.id DESC LIMIT 100");?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="professional_assets/app.css"><link rel="stylesheet" href="professional_assets/theme.css.php"><title>Nursing</title></head><body class="module-body"><div class="module-wrap"><div class="module-head"><div><span class="eyebrow">NURSING</span><h1>Nursing Workspace</h1><p>Assigned patients, vital signs, nursing notes and medication administration.</p></div></div><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><div class="panel"><h2>New nursing note</h2><form method="post" class="form-grid"><label>Patient<select name="patient_id" required><?php while($p=$patients->fetch_assoc()):?><option value="<?=$p['patientid']?>"><?=esc($p['patientname'])?></option><?php endwhile;?></select></label><label>Nurse name<input name="nurse_name"></label><label>Vital signs<input name="vitals" placeholder="BP, pulse, temperature..."></label><label>Medication administration<input name="medication"></label><label>Note<textarea name="note"></textarea></label><button class="primary-btn">Save nursing note</button></form></div><div class="panel"><h2>Nursing history</h2><div class="table-wrap"><table><thead><tr><th>Patient</th><th>Nurse</th><th>Vitals</th><th>Medication</th><th>Note</th><th>Date</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=esc($r['patientname'])?></td><td><?=esc($r['nurse_name'])?></td><td><?=esc($r['vitals'])?></td><td><?=esc($r['medication'])?></td><td><?=esc($r['note'])?></td><td><?=esc($r['created_at'])?></td></tr><?php endwhile;?></tbody></table></div></div></div></body></html>
